</main></div></div><script>(()=>{const b=document.querySelector('.menu-button'),o=document.querySelector('[data-close-menu]'),s=document.getElementById('admin-sidebar');if(!b||!s)return;const set=v=>{document.body.classList.toggle('nav-open',v);b.setAttribute('aria-expanded',v?'true':'false');b.setAttribute('aria-label',v?'Chiudi menu':'Apri menu')};b.addEventListener('click',()=>set(!document.body.classList.contains('nav-open')));o?.addEventListener('click',()=>set(false));s.addEventListener('click',e=>{if(e.target.closest('a')&&matchMedia('(max-width:980px)').matches)set(false)});document.addEventListener('keydown',e=>{if(e.key==='Escape')set(false)})})();</script></body></html>
